import{_ as c,r as t,o as l,c as r,e,a as s,d as a,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Модели - October CMS - 3.x","titleTemplate":false,"description":"Сопоставляйте столбцы таблицы базы данных непосредственно с PHP-объектом.","frontmatter":{"subtitle":"Сопоставляйте столбцы таблицы базы данных непосредственно с PHP-объектом."},"headers":[{"level":2,"title":"Определение моделей","slug":"определение-моделеи","link":"#определение-моделеи","children":[{"level":3,"title":"Поддерживаемые свойства","slug":"поддерживаемые-своиства","link":"#поддерживаемые-своиства","children":[{"level":4,"title":"Первичный ключ","slug":"первичныи-ключ","link":"#первичныи-ключ","children":[]},{"level":4,"title":"Автоинкремент","slug":"автоинкремент","link":"#автоинкремент","children":[]},{"level":4,"title":"Метки времени","slug":"метки-времени","link":"#метки-времени","children":[]},{"level":4,"title":"Значения, хранящиеся как JSON","slug":"значения-хранящиеся-как-json","link":"#значения-хранящиеся-как-json","children":[]}]}]},{"level":2,"title":"События модели","slug":"события-модели","link":"#события-модели","children":[{"level":3,"title":"Базовое использование","slug":"базовое-использование","link":"#базовое-использование","children":[]}]},{"level":2,"title":"Расширение моделей","slug":"расширение-моделеи","link":"#расширение-моделеи","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/extend/system/models.md","filePath":"3.x/ru/extend/system/models.md"}'),d={name:"3.x/ru/extend/system/models.md"};function u(k,n,g,h,f,m){const p=t("pre-heading"),o=t("post-heading");return l(),r("div",null,[e(p),n[0]||(n[0]=s("h1",null,"Модели",-1)),e(o),n[1]||(n[1]=s("p",null,[a("October CMS предоставляет красивую и простую реализацию Active Record для работы с вашей базой данных, основанную на "),s("a",{href:"http://laravel.com/docs/eloquent",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Eloquent от Laravel"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])]),a(". Каждая таблица базы данных имеет соответствующую «Модель», которая используется для взаимодействия с этой таблицей. Модели позволяют запрашивать данные из таблиц, а также вставлять новые записи.")],-1)),n[2]||(n[2]=i(`<p>Классы моделей находятся в поддиректории <strong>models</strong> директории плагина. Пример структуры директории модели.</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           ├── <code>models</code>
|           |   ├── post  <em>← Директория конфигурации</em>
|           |   |   ├── fields.yaml  <em>← Файл конфигурации</em>
|           |   |   └── columns.yaml  <em>← Файл конфигурации</em>
|           |   └── Post.php  <em>← Класс модели</em>
|           └── Plugin.php</p>
</code></pre><p>Директория конфигурации модели может содержать <a href="./../../element/form-fields.html">определения полей формы</a> модели. Имя директории конфигурации модели совпадает с именем класса модели в нижнем регистре.</p><h2 id="определение-моделеи"><a href="#определение-моделеи" class="header-anchor">#</a> Определение моделей</h2><p>Команда <code>create:model</code> генерирует файлы, необходимые для новой модели. Первый аргумент указывает имя автора и плагина. Второй аргумент указывает имя класса модели.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:model Acme.Blog Post
</code></pre></div><p>В большинстве случаев для каждой таблицы базы данных следует создавать один класс модели. Все классы моделей должны наследовать класс <code>Model</code>. Самое базовое представление модели, используемой внутри плагина, выглядит так.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Model</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$table</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme_blog_posts&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Защищённое поле <code>$table</code> указывает таблицу базы данных, соответствующую модели. Имя таблицы представляет собой snake_case имя автора, плагина и множественное число типа записи.</p><h3 id="поддерживаемые-своиства"><a href="#поддерживаемые-своиства" class="header-anchor">#</a> Поддерживаемые свойства</h3><p>Существует ряд стандартных свойств моделей, помимо тех, что предоставляются <a href="./traits.html">трейтами моделей</a>. Например:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$primaryKey</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$exists</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$dates</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;last_seen_at&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$timestamps</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$jsonable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;permissions&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$guarded</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>$primaryKey</strong></td><td>имя первичного ключа, используемого для идентификации модели.</td></tr><tr><td><strong>$incrementing</strong></td><td>логическое значение, если false — указывает, что первичный ключ не является автоинкрементным целым числом.</td></tr><tr><td><strong>$exists</strong></td><td>логическое значение, если true — указывает, что модель существует.</td></tr><tr><td><strong>$dates</strong></td><td>значения преобразуются в экземпляры объектов Carbon/DateTime после извлечения.</td></tr><tr><td><strong>$timestamps</strong></td><td>логическое значение, если true — автоматически устанавливает поля created_at и updated_at.</td></tr><tr><td><strong>$jsonable</strong></td><td>значения кодируются как JSON перед сохранением и преобразуются в массивы после извлечения.</td></tr><tr><td><strong>$fillable</strong></td><td>значения — поля, доступные для массового присваивания.</td></tr><tr><td><strong>$guarded</strong></td><td>значения — поля, защищённые от массового присваивания.</td></tr><tr><td><strong>$visible</strong></td><td>значения — поля, видимые при <a href="./../database/serialization.html">сериализации данных модели</a>.</td></tr><tr><td><strong>$hidden</strong></td><td>значения — поля, скрытые при <a href="./../database/serialization.html">сериализации данных модели</a>.</td></tr><tr><td><strong>$connection</strong></td><td>строка, содержащая <a href="./../../setup/database-config.html">имя подключения</a>, используемого моделью по умолчанию.</td></tr></tbody></table></div><h4 id="первичныи-ключ"><a href="#первичныи-ключ" class="header-anchor">#</a> Первичный ключ</h4><p>Модели предполагают, что каждая таблица имеет столбец первичного ключа с именем <code>id</code>. Вы можете определить свойство <code>$primaryKey</code> для переопределения этой конвенции.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$primaryKey</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="автоинкремент"><a href="#автоинкремент" class="header-anchor">#</a> Автоинкремент</h4><p>Модели предполагают, что первичный ключ является автоинкрементным целым числом, что означает, что по умолчанию первичный ключ будет автоматически приведён к целому числу. Если вы хотите использовать неинкрементный или нечисловой первичный ключ, установите публичное свойство <code>$incrementing</code> в false.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Message</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$incrementing</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="метки-времени"><a href="#метки-времени" class="header-anchor">#</a> Метки времени</h4><p>По умолчанию модель ожидает наличия столбцов <code>created_at</code> и <code>updated_at</code> в ваших таблицах. Если вы не хотите, чтобы эти столбцы управлялись автоматически, установите свойство <code>$timestamps</code> модели в <code>false</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$timestamps</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Если вам нужно настроить формат меток времени, установите свойство <code>$dateFormat</code> модели. Это свойство определяет, как атрибуты дат хранятся в базе данных, а также их формат при сериализации модели в массив или JSON.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$dateFormat</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;U&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="значения-хранящиеся-как-json"><a href="#значения-хранящиеся-как-json" class="header-anchor">#</a> Значения, хранящиеся как JSON</h4><p>Когда имена атрибутов передаются в свойство <code>$jsonable</code>, значения будут сериализованы и десериализованы из базы данных как JSON.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$jsonable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;data&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="события-модели"><a href="#события-модели" class="header-anchor">#</a> События модели</h2><p>Модели генерируют несколько событий, позволяя вам подключаться к различным точкам жизненного цикла модели. События позволяют легко выполнять код каждый раз, когда определённый класс модели сохраняется или обновляется в базе данных. События определяются путём переопределения специальных методов в классе, доступны следующие переопределения методов:</p><div class="table"><table tabindex="0"><thead><tr><th>Событие</th><th>Описание</th></tr></thead><tbody><tr><td><strong>beforeCreate</strong></td><td>перед сохранением модели при первом создании.</td></tr><tr><td><strong>afterCreate</strong></td><td>после сохранения модели при первом создании.</td></tr><tr><td><strong>beforeSave</strong></td><td>перед сохранением модели, будь то создание или обновление.</td></tr><tr><td><strong>afterSave</strong></td><td>после сохранения модели, будь то создание или обновление.</td></tr><tr><td><strong>beforeValidate</strong></td><td>перед валидацией предоставленных данных модели.</td></tr><tr><td><strong>afterValidate</strong></td><td>после валидации предоставленных данных модели.</td></tr><tr><td><strong>beforeUpdate</strong></td><td>перед сохранением существующей модели.</td></tr><tr><td><strong>afterUpdate</strong></td><td>после сохранения существующей модели.</td></tr><tr><td><strong>beforeDelete</strong></td><td>перед удалением существующей модели.</td></tr><tr><td><strong>afterDelete</strong></td><td>после удаления существующей модели.</td></tr><tr><td><strong>beforeRestore</strong></td><td>перед восстановлением мягко удалённой модели.</td></tr><tr><td><strong>afterRestore</strong></td><td>после восстановления мягко удалённой модели.</td></tr><tr><td><strong>beforeFetch</strong></td><td>перед заполнением существующей модели.</td></tr><tr><td><strong>afterFetch</strong></td><td>после заполнения существующей модели.</td></tr></tbody></table></div><p>Пример использования события.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token class-name static-context">Str</span><span class="token operator">::</span><span class="token function">slug</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="базовое-использование"><a href="#базовое-использование" class="header-anchor">#</a> Базовое использование</h3><p>Каждый раз, когда новая модель сохраняется впервые, будут вызваны события <code>beforeCreate</code> и <code>afterCreate</code>. Если модель уже существовала в базе данных и вызывается метод <code>save</code>, будут вызваны события <code>beforeUpdate</code> / <code>afterUpdate</code>. Однако в обоих случаях будут вызваны события <code>beforeSave</code> / <code>afterSave</code>.</p><p>Например, определим обработчик события, который заполняет атрибут <code>slug</code> при первом создании модели.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token class-name static-context">Str</span><span class="token operator">::</span><span class="token function">slug</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Возврат <code>false</code> из события отменит операцию <code>save</code> / <code>update</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">isValid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Можно получить доступ к старым значениям с помощью атрибута <code>original</code>. Например:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">afterUpdate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">title</span> <span class="token operator">!==</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">original</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Title has changed</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы можете обнаружить, что связи, созданные с использованием <a href="./../database/relations.html">отложенных привязок</a> (например, вложения файлов), ещё недоступны внутри событий модели. Для раннего доступа к ним используйте метод запроса к базе данных <code>withDeferred</code> на связи.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$avatar</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">avatar</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withDeferred</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$gallery</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">gallery</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withDeferred</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы можете внешне привязаться к <a href="./../services/event.html">локальным событиям</a> для одного экземпляра модели с помощью метода <code>bindEvent</code>. Имя события должно совпадать с именем переопределяемого метода с префиксом <code>model.</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Flight</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.beforeCreate&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token class-name static-context">Str</span><span class="token operator">::</span><span class="token function">slug</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="расширение-моделеи"><a href="#расширение-моделеи" class="header-anchor">#</a> Расширение моделей</h2><p>Поскольку модели <a href="./behaviors.html">приспособлены для использования поведений</a>, они могут быть расширены с помощью статического метода <code>extend</code>. Метод принимает замыкание и передаёт в него объект модели.</p><p>Внутри замыкания вы можете добавлять связи к модели. Здесь мы расширяем модель <code>User</code>, добавляя связь профиля (has one), ссылающуюся на модель <code>Profile</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">hasOne</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;profile&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token class-name static-context">Profile</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Этот подход также можно использовать для привязки к локальным событиям. Следующий код прослушивает событие <code>model.beforeSave</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.beforeSave&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Кроме того, существует несколько методов для расширения защищённых свойств модели.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Add cast attributes</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addCasts</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;some_extended_field&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;int&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Add a date attribute</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addDateAttribute</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;updated_at&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Adds fillable or jsonable fields</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addFillable</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;first_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addJsonable</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;some_data&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Как правило, лучшее место для размещения кода — метод <code>boot</code> вашего <a href="./../extending.html">файла регистрации плагина</a>, так как он выполняется при каждом запросе, обеспечивая доступность ваших расширений модели везде.</p><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../database/model.html">Запросы к модели</a></li><li><a href="./../database/traits.html">Трейты моделей</a></li></ul></div>`,55))])}const y=c(d,[["render",u]]);export{v as __pageData,y as default};
